Simulación 0.2.1
Qué representa cada mando. C es el número de núcleos de la CPU (el portátil del laboratorio tiene unos 10). G es el número de núcleos de la GPU (3 072 en la del laboratorio). v dice cuántas veces más deprisa trabaja un núcleo de CPU que uno de GPU: un núcleo de CPU funciona a mayor frecuencia y hace más trabajo por ciclo, y en la práctica es varias veces más rápido; aquí vale 6 por omisión. La tarea puede ser independiente, si el color de cada píxel se calcula sin mirar los demás, como al dibujar una imagen, o encadenada, si cada píxel necesita el resultado del anterior, como en una suma acumulada. El tiempo se mide en ciclos: lo que tarda un núcleo de GPU en calcular un píxel.

s02cg_widget = {
  const W = 160, H = 100, N = W * H;
  const miles = x =&gt; String(x).replace(/\B(?=(\d{3})+(?!\d))/g, " ");   // 16 000
  const raiz = html`&lt;div class="sim-cg"&gt;&lt;/div&gt;`;
  const estilo = getComputedStyle(document.querySelector(".simulacion") || document.body);
  const hex = v =&gt; {
    const c = document.createElement("canvas").getContext("2d");
    c.fillStyle = estilo.getPropertyValue(v).trim() || "#888"; c.fillRect(0, 0, 1, 1);
    return [...c.getImageData(0, 0, 1, 1).data].slice(0, 3);
  };
  const papel = hex("--sim-papel"), acento = hex("--sim-acento"), tinta = hex("--sim-tinta");
  // La «receta» de cada píxel: el número de iteraciones del conjunto de Mandelbrot.
  const color = new Uint8ClampedArray(N * 4);
  for (let y = 0; y &lt; H; y++) for (let x = 0; x &lt; W; x++) {
    const cr = -2.2 + 3.0 * x / W, ci = -1.2 + 2.4 * y / H;
    let zr = 0, zi = 0, k = 0;
    while (k &lt; 60 && zr * zr + zi * zi &lt; 4) { const t = zr * zr - zi * zi + cr; zi = 2 * zr * zi + ci; zr = t; k++; }
    const f = k / 60, base = (y * W + x) * 4;
    const m = f &lt; 0.5 ? [papel, acento, f * 2] : [acento, tinta, (f - 0.5) * 2];
    for (let c = 0; c &lt; 3; c++) color[base + c] = m[0][c] + (m[1][c] - m[0][c]) * m[2];
    color[base + 3] = 255;
  }
  const control = (rotulo, min, max, paso, valor) =&gt; {
    const e = html`&lt;label class="sim-cg-control"&gt;&lt;span&gt;${rotulo}&lt;/span&gt;&lt;input type="range" min=${min} max=${max} step=${paso} value=${valor}&gt;&lt;output&gt;${valor}&lt;/output&gt;&lt;/label&gt;`;
    const i = e.querySelector("input"), o = e.querySelector("output");
    i.oninput = () =&gt; { o.value = i.value; reiniciar(); };
    return {e, get: () =&gt; +i.value, set: v =&gt; { i.value = v; o.value = v; }};
  };
  const C = control("C, núcleos de la CPU", 1, 16, 1, 10);
  const G = control("G, núcleos de la GPU", 32, 3072, 32, 3072);
  const V = control("v, rapidez de un núcleo de CPU", 1, 12, 1, 6);
  const tarea = html`&lt;div class="sim-cg-tarea"&gt;&lt;span&gt;Tarea:&lt;/span&gt;
    &lt;label&gt;&lt;input type="radio" name="s02cg-tarea" value="indep" checked&gt; independiente (una imagen)&lt;/label&gt;
    &lt;label&gt;&lt;input type="radio" name="s02cg-tarea" value="cadena"&gt; encadenada (cada píxel espera al anterior)&lt;/label&gt;&lt;/div&gt;`;
  tarea.querySelectorAll("input").forEach(i =&gt; i.onchange = reiniciar);
  const esCadena = () =&gt; tarea.querySelector("input:checked").value === "cadena";
  const boton = (t, f) =&gt; { const b = html`&lt;button type="button"&gt;${t}&lt;/button&gt;`; b.onclick = f; return b; };
  const lienzo = rot =&gt; {
    const c = html`&lt;canvas width=${W} height=${H}&gt;&lt;/canvas&gt;`;
    return {fig: html`&lt;figure class="sim-cg-panel"&gt;&lt;figcaption&gt;${rot}&lt;/figcaption&gt;${c}&lt;div class="sim-cg-cuenta"&gt;&lt;/div&gt;&lt;/figure&gt;`, c};
  };
  const cpu = lienzo("CPU"), gpu = lienzo("GPU");
  const lectura = html`&lt;p class="sim-lectura"&gt;&lt;/p&gt;`;
  raiz.append(C.e, G.e, V.e, tarea,
    html`&lt;div class="sim-mem-botones"&gt;&lt;span class="sim-mem-rot"&gt;Pruebe:&lt;/span&gt;&lt;/div&gt;`,
    html`&lt;div class="sim-cg-lienzos"&gt;&lt;/div&gt;`, lectura);
  raiz.querySelector(".sim-mem-botones").append(
    boton("Pintar", () =&gt; arrancar()),
    boton("Una imagen (tarea paralela)", () =&gt; { tarea.querySelector('[value="indep"]').checked = true; C.set(10); G.set(3072); V.set(6); arrancar(); }),
    boton("Una cadena (tarea secuencial)", () =&gt; { tarea.querySelector('[value="cadena"]').checked = true; C.set(10); G.set(3072); V.set(6); arrancar(); }),
    boton("Una GPU pequeña", () =&gt; { tarea.querySelector('[value="indep"]').checked = true; C.set(10); G.set(64); V.set(6); arrancar(); }));
  raiz.querySelector(".sim-cg-lienzos").append(cpu.fig, gpu.fig);

  // Píxeles por ciclo de cada procesador.
  const ritmo = () =&gt; esCadena() ? {cpu: V.get(), gpu: 1} : {cpu: C.get() * V.get(), gpu: G.get()};
  let t = 0, marco = null, inicio = 0;
  const pintar = (p, n) =&gt; {
    const ctx = p.c.getContext("2d"), img = ctx.createImageData(W, H);
    img.data.set(color.subarray(0, n * 4)); ctx.putImageData(img, 0, 0);
  };
  const dibujar = () =&gt; {
    const r = ritmo();
    const nc = Math.min(N, Math.floor(r.cpu * t)), ng = Math.min(N, Math.floor(r.gpu * t));
    pintar(cpu, nc); pintar(gpu, ng);
    const tc = Math.ceil(N / r.cpu), tg = Math.ceil(N / r.gpu);
    cpu.fig.querySelector(".sim-cg-cuenta").textContent = nc &lt; N ? `${Math.round(t)} ciclos…` : `terminó en ${miles(tc)} ciclos`;
    gpu.fig.querySelector(".sim-cg-cuenta").textContent = ng &lt; N ? `${Math.round(t)} ciclos…` : `terminó en ${miles(tg)} ciclos`;
    const gana = tc &gt; tg ? `la GPU es ${(tc / tg).toFixed(1)} veces más rápida` : `la CPU es ${(tg / tc).toFixed(1)} veces más rápida`;
    lectura.innerHTML = `Imagen de ${miles(N)} píxeles. Píxeles por ciclo: CPU ${r.cpu}, GPU ${r.gpu}. Al final, &lt;b&gt;${gana}&lt;/b&gt;.`;
  };
  function reiniciar() { cancelAnimationFrame(marco); t = 0; dibujar(); }
  function arrancar() {
    cancelAnimationFrame(marco);
    const r = ritmo(), total = Math.max(N / r.cpu, N / r.gpu);
    const velocidad = total / 10000;              // el más lento termina en unos 10 segundos
    inicio = performance.now();
    const paso = ahora =&gt; { t = (ahora - inicio) * velocidad; dibujar(); if (t &lt; total) marco = requestAnimationFrame(paso); };
    marco = requestAnimationFrame(paso);
  }
  invalidation.then(() =&gt; cancelAnimationFrame(marco));
  dibujar();
  return raiz;
}






Cada procesador pinta la misma imagen, píxel a píxel, con todos los núcleos que puede usar a la vez. El color de cada píxel sale de una misma receta matemática (el número de iteraciones de z \mapsto z^2 + c antes de escapar del disco de radio 2).









