  return html`&lt;div class="sim-mem-botones"&gt;&lt;span class="sim-mem-rot"&gt;Pruebe:&lt;/span&gt;
    ${caso("Números parecidos", 1000, 0, false, "32 bits")}
    ${caso("Magnitudes muy dispares", 1000, 8, false, "32 bits")}
    ${caso("Signos mezclados", 1000, 4, true, "32 bits")}
    ${caso("Lo mismo en 64 bits", 1000, 8, false, "64 bits")}&lt;/div&gt;`;
}







s024_res = {
  s024_tanda;
  const gen = a =&gt; () =&gt; {   // mulberry32: generador pseudoaleatorio de 32 bits
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a);
    t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t;
    return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296;
  };
  const f32 = s024_prec === "32 bits";
  const r = gen(s024_semilla);
  const x = Array.from({length: s024_n}, () =&gt; {
    const v = (s024_signos && r() &lt; 0.5 ? -1 : 1) * 10 ** (r() * s024_dec) * (1 + r());
    return f32 ? Math.fround(v) : v;
  });
  const fsum = xs =&gt; {       // suma exacta redondeada (algoritmo de Shewchuk)
    const p = [];
    for (let v of xs) {
      let i = 0;
      for (let y of p) {
        if (Math.abs(v) &lt; Math.abs(y)) [v, y] = [y, v];
        const hi = v + y, lo = y - (hi - v);
        if (lo !== 0) p[i++] = lo;
        v = hi;
      }
      p.length = i; p.push(v);
    }
    return p.reduce((a, b) =&gt; a + b, 0);
  };
  const exacta = fsum(x);
  const escala = x.reduce((a, v) =&gt; a + Math.abs(v), 0);
  const rb = gen(1000 + s024_semilla * 7919 + Date.now() % 100000);
  const orden = x.slice();
  const res = [];
  for (let k = 0; k &lt; 400; k++) {
    for (let i = orden.length - 1; i &gt; 0; i--) {
      const j = Math.floor(rb() * (i + 1));
      [orden[i], orden[j]] = [orden[j], orden[i]];
    }
    let s = 0;
    for (const v of orden) s = f32 ? Math.fround(s + v) : s + v;
    res.push({s, err: (s - exacta) / escala});
  }
  return {res, distintos: new Set(res.map(d =&gt; d.s)).size, exacta};
}







